     1→//! rlibc-x2: A libc replacement for Rust std applications
     2→//!
     3→//! This crate provides the libc symbols needed to run Rust programs
     4→//! that use the standard library, without linking to glibc.
     5→//!
     6→//! # Usage
     7→//!
     8→//! Add to your Cargo.toml:
     9→//! ```toml
    10→//! [dependencies]
    11→//! rlibc-x2 = { path = "../rlibc-x2" }
    12→//! ```
    13→//!
    14→//! And in your build.rs:
    15→//! ```rust,ignore
    16→//! fn main() {
    17→//!     println!("cargo:rustc-link-arg=-static");
    18→//!     println!("cargo:rustc-link-arg=-nostdlib");
    19→//!     println!("cargo:rustc-link-arg=-nodefaultlibs");
    20→//!     println!("cargo:rustc-link-arg=-e_start");
    21→//!     println!("cargo:rustc-link-arg=-Wl,--undefined=_start");
    22→//!     println!("cargo:rustc-link-arg=-Wl,--undefined=__libc_start_main");
    23→//! }
    24→//! ```
    25→
    26→#![no_std]
    27→
    28→pub mod environ;
    29→pub mod errno;
    30→pub mod io;
    31→pub mod memory;
    32→pub mod process;
    33→pub mod signal;
    34→pub mod syscall;
    35→pub mod thread;
    36→
    37→// Re-export key symbols
    38→pub use environ::environ;
    39→pub use process::exit;
    40→
    41→// Note: We don't provide a panic handler because std provides one.
    42→// rlibc-x2 is designed to be used WITH std, just replacing libc.
    43→
    44→// Stubs for functions we haven't implemented yet
    45→// These print a message and exit so we know what's missing
    46→
    47→macro_rules! stub {
    48→    ($name:ident, $ret:ty) => {
    49→        #[unsafe(no_mangle)]
    50→        pub extern "C" fn $name() -> $ret {
    51→            let msg = concat!("STUB: ", stringify!($name), "\n");
    52→            io::write(2, msg.as_ptr(), msg.len());
    53→            process::exit(99)
    54→        }
    55→    };
    56→    ($name:ident) => {
    57→        #[unsafe(no_mangle)]
    58→        pub extern "C" fn $name() -> ! {
    59→            let msg = concat!("STUB: ", stringify!($name), "\n");
    60→            io::write(2, msg.as_ptr(), msg.len());
    61→            process::exit(99)
    62→        }
    63→    };
    64→}
    65→
    66→// File system stubs
    67→stub!(close, i32);
    68→stub!(dup, i32);
    69→stub!(fcntl, i32);
    70→stub!(fstat64, i32);
    71→stub!(lseek64, i64);
    72→stub!(open64, i32);
    73→stub!(stat64, i32);
    74→stub!(getcwd, *mut u8);
    75→stub!(readlink, isize);
    76→stub!(realpath, *mut u8);
    77→
    78→// Environment stubs
    79→stub!(getauxval, usize);
