//! rlibc-x2: A libc replacement for Rust std applications
//!
//! This crate provides the libc symbols needed to run Rust programs
//! that use the standard library, without linking to glibc.
//!
//! # Usage
//!
//! Add to your Cargo.toml:
//! ```toml
//! [dependencies]
//! rlibc-x2 = { path = "../rlibc-x2" }
//! ```
//!
//! And in your build.rs:
//! ```rust,ignore
//! fn main() {
//!     println!("cargo:rustc-link-arg=-static");
//!     println!("cargo:rustc-link-arg=-nostdlib");
//!     println!("cargo:rustc-link-arg=-nodefaultlibs");
//!     println!("cargo:rustc-link-arg=-e_start");
//!     println!("cargo:rustc-link-arg=-Wl,--undefined=_start");
//!     println!("cargo:rustc-link-arg=-Wl,--undefined=__libc_start_main");
//! }
//! ```

#![no_std]

pub mod environ;
pub mod errno;
pub mod io;
pub mod memory;
pub mod process;
pub mod signal;
pub mod syscall;
pub mod thread;

// Re-export key symbols
pub use environ::environ;
pub use process::exit;

// Note: We don't provide a panic handler because std provides one.
// rlibc-x2 is designed to be used WITH std, just replacing libc.

// Stubs for functions we haven't implemented yet
// These print a message and exit so we know what's missing

macro_rules! stub {
    ($name:ident, $ret:ty) => {
        #[unsafe(no_mangle)]
        pub extern "C" fn $name() -> $ret {
            let msg = concat!("STUB: ", stringify!($name), "\n");
            io::write(2, msg.as_ptr(), msg.len());
            process::exit(99)
        }
    };
    ($name:ident) => {
        #[unsafe(no_mangle)]
        pub extern "C" fn $name() -> ! {
            let msg = concat!("STUB: ", stringify!($name), "\n");
            io::write(2, msg.as_ptr(), msg.len());
            process::exit(99)
        }
    };
}

// File system stubs
stub!(close, i32);
stub!(dup, i32);
stub!(fcntl, i32);
stub!(fstat64, i32);
stub!(lseek64, i64);
stub!(open64, i32);
stub!(stat64, i32);
stub!(getcwd, *mut u8);
stub!(readlink, isize);
stub!(realpath, *mut u8);

// Environment stubs
stub!(getauxval, usize);

// Memory mapping stubs
stub!(mmap64, *mut u8);
stub!(mprotect, i32);
stub!(munmap, i32);

// Generic syscall - all x86_64 Linux syscalls use at most 6 arguments
#[unsafe(no_mangle)]
pub extern "C" fn syscall(
    num: i64,
    arg1: u64,
    arg2: u64,
    arg3: u64,
    arg4: u64,
    arg5: u64,
    arg6: u64,
) -> i64 {
    unsafe { syscall::syscall6(num as u64, arg1, arg2, arg3, arg4, arg5, arg6) as i64 }
}

// Unwinding stubs (for panic/backtrace)
stub!(_Unwind_Backtrace, i32);
stub!(_Unwind_DeleteException);
stub!(_Unwind_GetDataRelBase, usize);
stub!(_Unwind_GetIP, usize);
stub!(_Unwind_GetIPInfo, usize);
stub!(_Unwind_GetLanguageSpecificData, *mut u8);
stub!(_Unwind_GetRegionStart, usize);
stub!(_Unwind_GetTextRelBase, usize);
stub!(_Unwind_RaiseException, i32);
stub!(_Unwind_Resume);
stub!(_Unwind_SetGR);
stub!(_Unwind_SetIP);

// Dynamic linking stubs
stub!(dl_iterate_phdr, i32);

//! Raw syscall wrappers for Linux x86_64

use core::arch::asm;

/// Invoke a syscall with 0 arguments.
///
/// # Safety
/// Caller must ensure `n` is a valid syscall number and that invoking
/// this syscall is safe in the current context.
#[inline(always)]
pub unsafe fn syscall0(n: u64) -> u64 {
    let ret: u64;
    unsafe {
        asm!(
            "syscall",
            in("rax") n,
            lateout("rax") ret,
            lateout("rcx") _,
            lateout("r11") _,
            options(nostack)
        );
    }
    ret
}

/// Invoke a syscall with 1 argument.
///
/// # Safety
/// Caller must ensure `n` is a valid syscall number and all arguments
/// are valid for that syscall.
#[inline(always)]
pub unsafe fn syscall1(n: u64, arg1: u64) -> u64 {
    let ret: u64;
    unsafe {
        asm!(
            "syscall",
            in("rax") n,
            in("rdi") arg1,
            lateout("rax") ret,
            lateout("rcx") _,
            lateout("r11") _,
            options(nostack)
        );
    }
    ret
}

/// Invoke a syscall with 2 arguments.
///
/// # Safety
/// Caller must ensure `n` is a valid syscall number and all arguments
/// are valid for that syscall.
#[inline(always)]
pub unsafe fn syscall2(n: u64, arg1: u64, arg2: u64) -> u64 {
    let ret: u64;
    unsafe {
        asm!(
            "syscall",
            in("rax") n,
            in("rdi") arg1,
            in("rsi") arg2,
            lateout("rax") ret,
            lateout("rcx") _,
            lateout("r11") _,
            options(nostack)
        );
    }
    ret
}

/// Invoke a syscall with 3 arguments.
///
/// # Safety
/// Caller must ensure `n` is a valid syscall number and all arguments
/// are valid for that syscall.
#[inline(always)]
pub unsafe fn syscall3(n: u64, arg1: u64, arg2: u64, arg3: u64) -> u64 {
    let ret: u64;
    unsafe {
        asm!(
            "syscall",
            in("rax") n,
            in("rdi") arg1,
            in("rsi") arg2,
            in("rdx") arg3,
            lateout("rax") ret,
            lateout("rcx") _,
            lateout("r11") _,
            options(nostack)
        );
    }
    ret
}

/// Invoke a syscall with 4 arguments.
///
/// # Safety
/// Caller must ensure `n` is a valid syscall number and all arguments
/// are valid for that syscall.
#[inline(always)]
pub unsafe fn syscall4(n: u64, arg1: u64, arg2: u64, arg3: u64, arg4: u64) -> u64 {
    let ret: u64;
    unsafe {
        asm!(
            "syscall",
            in("rax") n,
            in("rdi") arg1,
            in("rsi") arg2,
            in("rdx") arg3,
            in("r10") arg4,
            lateout("rax") ret,
            lateout("rcx") _,
            lateout("r11") _,
            options(nostack)
        );
    }
    ret
}

/// Invoke a syscall with 5 arguments.
///
/// # Safety
/// Caller must ensure `n` is a valid syscall number and all arguments
/// are valid for that syscall.
#[inline(always)]
pub unsafe fn syscall5(n: u64, arg1: u64, arg2: u64, arg3: u64, arg4: u64, arg5: u64) -> u64 {
    let ret: u64;
    unsafe {
        asm!(
            "syscall",
            in("rax") n,
            in("rdi") arg1,
            in("rsi") arg2,
            in("rdx") arg3,
            in("r10") arg4,
            in("r8") arg5,
            lateout("rax") ret,
            lateout("rcx") _,
            lateout("r11") _,
            options(nostack)
        );
    }
    ret
}

/// Invoke a syscall with 6 arguments.
///
/// # Safety
/// Caller must ensure `n` is a valid syscall number and all arguments
/// are valid for that syscall.
#[inline(always)]
pub unsafe fn syscall6(
    n: u64,
    arg1: u64,
    arg2: u64,
    arg3: u64,
    arg4: u64,
    arg5: u64,
    arg6: u64,
) -> u64 {
    let ret: u64;
    unsafe {
        asm!(
            "syscall",
            in("rax") n,
            in("rdi") arg1,
            in("rsi") arg2,
            in("rdx") arg3,
            in("r10") arg4,
            in("r8") arg5,
            in("r9") arg6,
            lateout("rax") ret,
            lateout("rcx") _,
            lateout("r11") _,
            options(nostack)
        );
    }
    ret
}

// Syscall numbers for Linux x86_64
pub const SYS_READ: u64 = 0;
pub const SYS_WRITE: u64 = 1;
pub const SYS_POLL: u64 = 7;
pub const SYS_BRK: u64 = 12;
pub const SYS_EXIT: u64 = 60;
pub const SYS_ARCH_PRCTL: u64 = 158;

// arch_prctl commands
pub const ARCH_SET_FS: u64 = 0x1002;
pub const ARCH_GET_FS: u64 = 0x1003;

